// Work MVP - To do List 모드 컴포넌트
import React, { useState } from 'react';
import type { ProjectTodo, ProjectTask, Project } from '../../types/work';
import { isReadOnlyItem } from '../../utils/scheduleAdapter';
import './TodoList.css';

interface TodoListProps {
  todos: ProjectTodo[];
  doneTodos: ProjectTodo[];
  tasks: ProjectTask[];
  projects: Project[];
  showCompleted: boolean;
  onAddClick: () => void; // + 버튼 클릭 시 팝업
  onSelectTodo: (todo: ProjectTodo) => void;
  onCompleteTodo: (todoId: string) => Promise<void>;
  onUndoComplete: (todoId: string) => Promise<void>;
  onReorderTodos: (todoIds: string[]) => Promise<void>;
  onDeleteScheduleTodo?: (todoId: string) => Promise<void>; // 일정관리 todo 삭제
  selectedTodoId?: string | null;
}

export default function TodoList({
  todos,
  doneTodos,
  tasks,
  projects,
  showCompleted,
  onAddClick,
  onSelectTodo,
  onCompleteTodo,
  onUndoComplete,
  onReorderTodos,
  onDeleteScheduleTodo,
  selectedTodoId,
}: TodoListProps) {
  const [draggedId, setDraggedId] = useState<string | null>(null);
  const [dragOverId, setDragOverId] = useState<string | null>(null);

  // 완료 토글
  const handleToggleComplete = async (e: React.MouseEvent, todo: ProjectTodo) => {
    e.stopPropagation();
    try {
      if (todo.is_done) {
        await onUndoComplete(todo.id);
      } else {
        await onCompleteTodo(todo.id);
      }
    } catch (error) {
      console.error('Failed to toggle todo completion:', error);
    }
  };

  // 드래그 시작
  const handleDragStart = (e: React.DragEvent, todoId: string) => {
    setDraggedId(todoId);
    e.dataTransfer.effectAllowed = 'move';
    e.dataTransfer.setData('text/plain', todoId);
    const target = e.target as HTMLElement;
    target.style.opacity = '0.5';
  };

  // 드래그 종료
  const handleDragEnd = (e: React.DragEvent) => {
    const target = e.target as HTMLElement;
    target.style.opacity = '1';
    setDraggedId(null);
    setDragOverId(null);
  };

  // 드래그 오버
  const handleDragOver = (e: React.DragEvent, todoId: string) => {
    e.preventDefault();
    e.dataTransfer.dropEffect = 'move';
    if (todoId !== draggedId) {
      setDragOverId(todoId);
    }
  };

  // 드롭
  const handleDrop = async (e: React.DragEvent, targetId: string) => {
    e.preventDefault();

    if (!draggedId || draggedId === targetId) {
      setDraggedId(null);
      setDragOverId(null);
      return;
    }

    const currentOrder = todos.map(t => t.id);
    const draggedIndex = currentOrder.indexOf(draggedId);
    const targetIndex = currentOrder.indexOf(targetId);

    if (draggedIndex === -1 || targetIndex === -1) return;

    const newOrder = [...currentOrder];
    newOrder.splice(draggedIndex, 1);
    newOrder.splice(targetIndex, 0, draggedId);

    try {
      await onReorderTodos(newOrder);
    } catch (error) {
      console.error('Failed to reorder todos:', error);
    }

    setDraggedId(null);
    setDragOverId(null);
  };

  // 태스크 정보 가져오기
  const getTaskInfo = (taskId: string | null): { name: string; color: string } => {
    if (!taskId) return { name: '미분류', color: '#64748b' };
    const task = tasks.find(t => t.id === taskId);
    if (!task) return { name: '미분류', color: '#64748b' };
    
    // 태스크가 속한 프로젝트 색상
    const project = projects.find(p => p.id === task.projectId);
    return { 
      name: task.title, 
      color: project?.color || '#64748b' 
    };
  };

  // 날짜 포맷
  const formatDate = (dateStr: string | null): string => {
    if (!dateStr) return '';
    const date = new Date(dateStr);
    return date.toLocaleDateString('ko-KR', { month: 'short', day: 'numeric' });
  };

  // 일정관리 todo 삭제 핸들러
  const handleDeleteScheduleTodo = async (e: React.MouseEvent, todoId: string) => {
    e.stopPropagation();
    if (!onDeleteScheduleTodo) return;
    if (confirm('정말로 이 To do를 삭제하시겠습니까?')) {
      try {
        await onDeleteScheduleTodo(todoId);
      } catch (error) {
        console.error('Failed to delete schedule todo:', error);
      }
    }
  };

  return (
    <div className="work-todo-list">
      {/* + 버튼 */}
      <button className="add-todo-btn-large" onClick={onAddClick}>
        + 새 To do
      </button>

      {/* 활성 투두 목록 */}
      <div className="todos-section">
        {todos.length === 0 ? (
          <div className="empty-todos">
            <span className="empty-icon">📝</span>
            <p>To do가 없습니다</p>
            <p className="empty-hint">위 버튼을 눌러 새 To do를 만들어보세요</p>
          </div>
        ) : (
          <ul className="todos-items">
            {todos.map((todo) => {
              const taskInfo = getTaskInfo(todo.taskId);
              const isReadOnly = isReadOnlyItem(todo.id);
              return (
                <li
                  key={todo.id}
                  className={`todo-item ${selectedTodoId === todo.id ? 'selected' : ''} ${dragOverId === todo.id ? 'drag-over' : ''} ${isReadOnly ? 'read-only' : ''}`}
                  draggable={!isReadOnly}
                  onDragStart={(e) => !isReadOnly && handleDragStart(e, todo.id)}
                  onDragEnd={handleDragEnd}
                  onDragOver={(e) => !isReadOnly && handleDragOver(e, todo.id)}
                  onDrop={(e) => !isReadOnly && handleDrop(e, todo.id)}
                  onClick={() => !isReadOnly && onSelectTodo(todo)}
                >
                  {!isReadOnly ? (
                    <button
                      className="complete-btn"
                      onClick={(e) => handleToggleComplete(e, todo)}
                      title="완료 처리"
                    >
                      ○
                    </button>
                  ) : (
                    <span className="readonly-badge" title="일정관리에서 가져온 항목">📋</span>
                  )}
                  <span
                    className="todo-task-indicator"
                    style={{ backgroundColor: isReadOnly ? '#64748b' : taskInfo.color }}
                    title={isReadOnly ? '일정 To do' : taskInfo.name}
                  />
                  <div className="todo-content">
                    <span className="todo-text">{todo.content}</span>
                    <div className="todo-meta">
                      <span className="todo-task-name">{isReadOnly ? '일정' : taskInfo.name}</span>
                      {/* 일정관리 todo는 날짜 하나만 표시 */}
                      {isReadOnly && todo.due_at && (
                        <span className="todo-dates">{formatDate(todo.due_at)}</span>
                      )}
                      {/* 작업 todo는 시작/마감일 표시 (마감일 없이) */}
                      {!isReadOnly && todo.start_at && (
                        <span className="todo-dates">{formatDate(todo.start_at)}</span>
                      )}
                    </div>
                  </div>
                  {!isReadOnly && <span className="drag-handle">⋮⋮</span>}
                  {/* 일정관리 todo 삭제 버튼 */}
                  {isReadOnly && onDeleteScheduleTodo && (
                    <button
                      className="delete-schedule-todo-btn"
                      onClick={(e) => handleDeleteScheduleTodo(e, todo.id)}
                      title="삭제"
                    >
                      ×
                    </button>
                  )}
                </li>
              );
            })}
          </ul>
        )}
      </div>

      {/* 완료된 투두 */}
      {showCompleted && doneTodos.length > 0 && (
        <div className="completed-section">
          <div className="section-header">
            <span className="section-title">✓ 완료됨</span>
            <span className="section-count">{doneTodos.length}</span>
          </div>
          <ul className="todos-items completed">
            {doneTodos.map((todo) => {
              const taskInfo = getTaskInfo(todo.taskId);
              return (
                <li
                  key={todo.id}
                  className={`todo-item completed ${selectedTodoId === todo.id ? 'selected' : ''}`}
                  onClick={() => onSelectTodo(todo)}
                >
                  <button
                    className="complete-btn done"
                    onClick={(e) => handleToggleComplete(e, todo)}
                    title="완료 취소"
                  >
                    ✓
                  </button>
                  <span
                    className="todo-task-indicator"
                    style={{ backgroundColor: taskInfo.color, opacity: 0.5 }}
                  />
                  <div className="todo-content">
                    <span className="todo-text">{todo.content}</span>
                    {todo.completed_at && (
                      <span className="todo-dates">
                        완료: {new Date(todo.completed_at).toLocaleDateString('ko-KR')}
                      </span>
                    )}
                  </div>
                </li>
              );
            })}
          </ul>
        </div>
      )}
    </div>
  );
}
